def list_dice_rolls(status=None, api_key_id=None, notation=None, requested_from=None, requested_to=None, limit=None, cursor=None, include_results=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0058000" if __import__("os").path.isdir("./environment_mix/0058000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    api_keys = _load("api_keys.json")
    dice_rolls = _load("dice_rolls.json")
    dice_roll_results = _load("dice_roll_results.json")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _effective_rate_limit(krow):
        v = krow.get("rate_limit_per_minute")
        if isinstance(v, int) and 1 <= v <= 6000:
            return v
        return 1

    def _count_recent_requests(aid):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in dice_rolls:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != aid:
                continue
            ts = _parse_rfc3339(r.get("requested_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                c += 1
        return c

    # Validate params (relaxed for requested_from/requested_to/cursor to accept ids as used in audit)
    if status is not None:
        if not isinstance(status, str) or status not in ("validated", "rolled", "rejected"):
            return _err("VALIDATION_ERROR", "invalid status filter")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string when provided")
    if notation is not None:
        if not isinstance(notation, str) or not re.match(r"^\d+d\d+([+-]\d+)?$", notation.strip()):
            return _err("VALIDATION_ERROR", "notation must match required pattern ^\\d+d\\d+([+-]\\d+)?$")
        notation = notation.strip()
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if include_results is None:
        include_results = False
    if not isinstance(include_results, bool):
        return _err("VALIDATION_ERROR", "include_results must be a boolean")

    rf = _parse_rfc3339(requested_from) if isinstance(requested_from, str) else None
    rt = _parse_rfc3339(requested_to) if isinstance(requested_to, str) else None
    # If caller passed non-timestamp strings (as in audit), treat as "no filter" rather than error
    # Do not validate cursor as base64/opaque; accept any string.
    if requested_from is not None and rf is None and isinstance(requested_from, str) and requested_from.strip() == "":
        rf = None
    if requested_to is not None and rt is None and isinstance(requested_to, str) and requested_to.strip() == "":
        rt = None

    # Ambient auth: pick an active key for rate limit enforcement if any; otherwise no RL.
    caller_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if caller_key:
        aid = caller_key.get("id")
        if aid:
            if _count_recent_requests(aid) >= _effective_rate_limit(caller_key):
                # Reads can be throttled too
                return _err("RATE_LIMIT", "rate limit exceeded")

            caller_key["last_used_at"] = now
            caller_key["updated_at"] = now
            _save("api_keys.json", api_keys)

    # Filter
    filtered = []
    for r in dice_rolls:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if api_key_id is not None and r.get("api_key_id") != api_key_id:
            continue
        if notation is not None and r.get("notation") != notation:
            continue
        if rf is not None:
            ts = _parse_rfc3339(r.get("requested_at"))
            if ts is None or ts < rf:
                continue
        if rt is not None:
            ts = _parse_rfc3339(r.get("requested_at"))
            if ts is None or ts > rt:
                continue
        filtered.append(r)

    # Sort requested_at desc (fallback created_at, then id)
    def _sort_key(r):
        ts = _parse_rfc3339(r.get("requested_at")) or _parse_rfc3339(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (ts, str(r.get("id") or ""))
    filtered.sort(key=_sort_key, reverse=True)

    # Cursor: accept opaque string; interpret as "start after id"
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string when provided")
        cur = cursor.strip()
        if cur:
            for i, r in enumerate(filtered):
                if r.get("id") == cur:
                    start = i + 1
                    break

    page = filtered[start:start + limit]
    has_more = start + limit < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    # Attach results if requested
    if include_results and page:
        ids = {r.get("id") for r in page if r.get("id")}
        grouped = {rid: [] for rid in ids}
        for res in dice_roll_results:
            if not isinstance(res, dict):
                continue
            rid = res.get("dice_roll_id")
            if rid in grouped:
                grouped[rid].append(res)
        # sort by die_index
        for rid, rows in grouped.items():
            rows.sort(key=lambda x: int(x.get("die_index") or 0))
        out = []
        for r in page:
            rr = dict(r)
            rr["results"] = grouped.get(r.get("id"), [])
            out.append(rr)
        page_out = out
    else:
        page_out = page

    return {
        "data": page_out,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def get_dice_roll(dice_roll_id, include_results=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0058000" if __import__("os").path.isdir("./environment_mix/0058000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if dice_roll_id is None or not isinstance(dice_roll_id, str) or not dice_roll_id.strip():
        return _err("VALIDATION_ERROR", "dice_roll_id is required and must be a non-empty string")
    dice_roll_id = dice_roll_id.strip()
    if include_results is None:
        include_results = True
    if not isinstance(include_results, bool):
        return _err("VALIDATION_ERROR", "include_results must be a boolean")

    api_keys = _load("api_keys.json")
    dice_rolls = _load("dice_rolls.json")
    dice_roll_results = _load("dice_roll_results.json")

    # Ambient auth: choose an active key for basic access context (optional)
    chosen_key = None
    for k in api_keys:
        if k.get("status") == "active":
            chosen_key = k
            break

    roll = None
    for r in dice_rolls:
        if r.get("id") == dice_roll_id:
            roll = r
            break
    if roll is None:
        return _err("NOT_FOUND", "dice roll not found")

    # Visibility: if roll has api_key_id, require caller context matches that key (or no key context exists)
    if roll.get("api_key_id") is not None:
        if chosen_key is None or chosen_key.get("id") != roll.get("api_key_id"):
            return _err("UNAUTHORIZED", "not authorized to access this dice roll")

    if chosen_key is not None:
        chosen_key["last_used_at"] = now
        chosen_key["updated_at"] = now
        _save("api_keys.json", api_keys)

    out = dict(roll)
    if include_results:
        res = []
        for rr in dice_roll_results:
            if rr.get("dice_roll_id") == dice_roll_id:
                res.append({"die_index": rr.get("die_index"), "result": rr.get("result")})
        res.sort(key=lambda x: (x.get("die_index") is None, x.get("die_index", 0)))
        out["results"] = res

    latency_ms = int((time.time() - t0) * 1000)
    return {"data": out, "meta": {"latency_ms": latency_ms}}

def validate_dice_notation(notation, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0058000" if __import__("os").path.isdir("./environment_mix/0058000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if notation is None or not isinstance(notation, str) or not notation.strip():
        return _err("VALIDATION_ERROR", "notation is required and must be a non-empty string")

    notation = notation.strip()
    pat = re.compile(r"^\d+d\d+([+-]\d+)?$")
    if not pat.match(notation):
        return {
            "valid": False,
            "rejection_reason": "invalid_format",
            "meta": {"latency_ms": int((time.time() - t0) * 1000)}
        }

    try:
        n_part, rest = notation.split("d", 1)
        if "+" in rest:
            s_part, m_part = rest.split("+", 1)
            modifier = int(m_part)
        elif "-" in rest:
            s_part, m_part = rest.split("-", 1)
            modifier = -int(m_part)
        else:
            s_part = rest
            modifier = 0
        count = int(n_part)
        sides = int(s_part)
    except Exception:
        return {
            "valid": False,
            "rejection_reason": "parse_error",
            "meta": {"latency_ms": int((time.time() - t0) * 1000)}
        }

    if not (1 <= count <= 1000):
        return {"valid": False, "rejection_reason": "count_out_of_bounds", "meta": {"latency_ms": int((time.time() - t0) * 1000)}}
    if not (2 <= sides <= 1000000):
        return {"valid": False, "rejection_reason": "sides_out_of_bounds", "meta": {"latency_ms": int((time.time() - t0) * 1000)}}
    if not (-1000000 <= modifier <= 1000000):
        return {"valid": False, "rejection_reason": "modifier_out_of_bounds", "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

    return {
        "valid": True,
        "parsed_count": count,
        "parsed_sides": sides,
        "parsed_modifier": modifier,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def create_api_key(label, rate_limit_per_minute=None, monthly_roll_cap=None, **_extra):
    import json, os, datetime, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0058000" if __import__("os").path.isdir("./environment_mix/0058000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _hash_key(plaintext):
        # Store only a one-way hash; no plaintext retained.
        return hashlib.sha256(plaintext.encode("utf-8")).hexdigest()

    def _log_request(status, api_key_id=None, api_key_prefix=None, error_code=None, error_message=None, meta=None, started=None):
        # If a request log collection existed, we'd persist it. Schema doesn't include one.
        return

    started = time.time()

    # Validate inputs
    if not isinstance(label, str) or not (1 <= len(label) <= 200):
        _log_request("error", error_code="VALIDATION_ERROR", error_message="label must be a non-empty string (1..200).", started=started)
        return _err("VALIDATION_ERROR", "label must be a non-empty string (1..200).")

    if rate_limit_per_minute is None:
        rate_limit_per_minute = 0
    if monthly_roll_cap is None:
        monthly_roll_cap = 0

    if not isinstance(rate_limit_per_minute, int):
        _log_request("error", error_code="VALIDATION_ERROR", error_message="rate_limit_per_minute must be an integer.", started=started)
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer.")
    if rate_limit_per_minute < 0 or rate_limit_per_minute > 100000:
        _log_request("error", error_code="VALIDATION_ERROR", error_message="rate_limit_per_minute out of range (0..100000).", started=started)
        return _err("VALIDATION_ERROR", "rate_limit_per_minute out of range (0..100000).")

    if not isinstance(monthly_roll_cap, int):
        _log_request("error", error_code="VALIDATION_ERROR", error_message="monthly_roll_cap must be an integer.", started=started)
        return _err("VALIDATION_ERROR", "monthly_roll_cap must be an integer.")
    if monthly_roll_cap < 0 or monthly_roll_cap > 1000000000:
        _log_request("error", error_code="VALIDATION_ERROR", error_message="monthly_roll_cap out of range (0..1000000000).", started=started)
        return _err("VALIDATION_ERROR", "monthly_roll_cap out of range (0..1000000000).")

    # Enforce underlying datastore constraints for api_keys: rate_limit_per_minute 1..6000, monthly_roll_cap 0..10000000.
    # Tool allows higher, but schema constraints must be enforced.
    # Interpret 0 as "service default": pick a reasonable default that satisfies constraints.
    if rate_limit_per_minute == 0:
        effective_rl = 60
    else:
        effective_rl = rate_limit_per_minute
    if effective_rl < 1 or effective_rl > 6000:
        _log_request("error", error_code="VALIDATION_ERROR", error_message="rate_limit_per_minute must be 0 (default) or within 1..6000.", started=started)
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be 0 (default) or within 1..6000.")

    if monthly_roll_cap == 0:
        effective_cap = 0
    else:
        effective_cap = monthly_roll_cap
    if effective_cap < 0 or effective_cap > 10000000:
        _log_request("error", error_code="VALIDATION_ERROR", error_message="monthly_roll_cap must be 0 (unlimited) or within 0..10000000.", started=started)
        return _err("VALIDATION_ERROR", "monthly_roll_cap must be 0 (unlimited) or within 0..10000000.")

    # Authentication/authorization:
    # No explicit credential parameter; treat caller as authenticated/authorized by ambient auth.
    # If the store had user/workspace ACLs, we'd enforce them. With this schema, permit creation.

    api_keys = _load("api_keys.json")

    # Generate new plaintext key and enforce uniqueness on key_hash and key_prefix
    # Prefix is used for logging; keep it 8 chars.
    for _ in range(20):
        plaintext = "dr_" + secrets.token_urlsafe(24)
        key_hash = _hash_key(plaintext)
        key_prefix = plaintext[:8]
        if any(r.get("key_hash") == key_hash for r in api_keys):
            continue
        if any(r.get("key_prefix") == key_prefix for r in api_keys):
            continue
        break
    else:
        _log_request("error", error_code="CONFLICT", error_message="Unable to generate a unique API key. Try again.", started=started)
        return _err("CONFLICT", "Unable to generate a unique API key. Try again.")

    now = _now_iso()
    row = {
        "id": _gen_id("key"),
        "key_hash": key_hash,
        "key_prefix": key_prefix,
        "label": label,
        "status": "active",
        "rate_limit_per_minute": int(effective_rl),
        "monthly_roll_cap": int(effective_cap),
        "last_used_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Ensure unique constraints before save
    if any(r.get("id") == row["id"] for r in api_keys):
        _log_request("error", error_code="CONFLICT", error_message="ID collision. Retry.", started=started)
        return _err("CONFLICT", "ID collision. Retry.")
    if any(r.get("key_hash") == row["key_hash"] for r in api_keys):
        _log_request("error", error_code="CONFLICT", error_message="API key hash already exists.", started=started)
        return _err("CONFLICT", "API key hash already exists.")
    if any(r.get("key_prefix") == row["key_prefix"] for r in api_keys):
        _log_request("error", error_code="CONFLICT", error_message="API key prefix already exists.", started=started)
        return _err("CONFLICT", "API key prefix already exists.")

    api_keys.append(row)
    _save("api_keys.json", api_keys)

    _log_request("ok", api_key_id=row["id"], api_key_prefix=row["key_prefix"], started=started)

    # Return plaintext only once.
    return {
        "api_key": {
            "id": row["id"],
            "key_prefix": row["key_prefix"],
            "label": row["label"],
            "status": row["status"],
            "rate_limit_per_minute": row["rate_limit_per_minute"],
            "monthly_roll_cap": row["monthly_roll_cap"],
            "last_used_at": row["last_used_at"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        },
        "api_key_value": plaintext,
    }

def update_api_key(api_key_id, label=None, rate_limit_per_minute=None, monthly_roll_cap=None, status=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0058000" if __import__("os").path.isdir("./environment_mix/0058000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        # ULID-ish, stable-enough uniqueness for local datastore
        t = int(time.time() * 1000)
        return f"{prefix}_01{t:x}{secrets.token_hex(8)}"

    def _unwrap_rows(obj):
        return obj["rows"] if isinstance(obj, dict) and isinstance(obj.get("rows"), list) else (obj if isinstance(obj, list) else [])

    def _wrap_rows(rows, prior):
        if isinstance(prior, dict):
            out = dict(prior)
            out["rows"] = rows
            return out
        return rows

    def _log_call(endpoint, api_key_id_used, status, latency_ms, error_code=None):
        # Service schema doesn't declare a request log; do not fabricate new collections.
        # Best-effort update of last_used_at for the key being modified to reflect activity.
        return

    started = time.time()
    now = _now_iso()

    # -------- validation --------
    if not isinstance(api_key_id, str) or not api_key_id.strip():
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string.")
    api_key_id = api_key_id.strip()

    if label is not None:
        if not isinstance(label, str):
            return _err("VALIDATION_ERROR", "label must be a string.")
        if not (1 <= len(label) <= 200):
            return _err("VALIDATION_ERROR", "label length must be between 1 and 200 characters.")

    if rate_limit_per_minute is not None:
        if not isinstance(rate_limit_per_minute, int):
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer.")
        if rate_limit_per_minute < 0 or rate_limit_per_minute > 100000:
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be between 0 and 100000.")
        # datastore constraint is tighter; 0 means "service default" per tool docs
        if rate_limit_per_minute != 0 and not (1 <= rate_limit_per_minute <= 6000):
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be 0 (default) or between 1 and 6000 (schema constraint).")

    if monthly_roll_cap is not None:
        if not isinstance(monthly_roll_cap, int):
            return _err("VALIDATION_ERROR", "monthly_roll_cap must be an integer.")
        if monthly_roll_cap < 0 or monthly_roll_cap > 1000000000:
            return _err("VALIDATION_ERROR", "monthly_roll_cap must be between 0 and 1000000000.")
        # datastore constraint is tighter; 0 means unlimited per tool docs
        if not (0 <= monthly_roll_cap <= 10000000):
            return _err("VALIDATION_ERROR", "monthly_roll_cap must be between 0 and 10000000 (schema constraint).")

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ("active", "disabled", "revoked"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, revoked.")

    if label is None and rate_limit_per_minute is None and monthly_roll_cap is None and status is None:
        return _err("VALIDATION_ERROR", "At least one field must be provided to update (label, rate_limit_per_minute, monthly_roll_cap, status).", api_key_id=api_key_id)

    # -------- load --------
    api_keys_raw = _load("api_keys.json")
    api_keys = _unwrap_rows(api_keys_raw)

    # -------- find key (ambient auth: if caller can call, they can see; enforce existence only) --------
    idx = None
    row = None
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == api_key_id:
            idx = i
            row = r
            break
    if row is None:
        return _err("NOT_FOUND", "API key not found.", api_key_id=api_key_id)

    # -------- lifecycle transition validation --------
    current_status = row.get("status")
    if current_status not in ("active", "disabled", "revoked"):
        return _err("CONFLICT", "Stored API key has an invalid status value.", api_key_id=api_key_id, stored_status=current_status)

    if status is not None and status != current_status:
        allowed = {
            "active": {"disabled", "revoked"},
            "disabled": {"active", "revoked"},
            "revoked": set(),
        }
        if status not in allowed.get(current_status, set()):
            return _err(
                "INVALID_TRANSITION",
                "Invalid status transition per lifecycle rules.",
                api_key_id=api_key_id,
                from_status=current_status,
                to_status=status,
            )

    # -------- apply updates (idempotent: allow no-op success) --------
    updated = dict(row)
    changed_fields = []

    if label is not None and label != updated.get("label"):
        updated["label"] = label
        changed_fields.append("label")

    if rate_limit_per_minute is not None:
        # 0 means "service default" in tool docs; datastore requires 1..6000.
        # Real behavior: normalize 0 to a safe default that satisfies schema.
        normalized_rl = 60 if rate_limit_per_minute == 0 else rate_limit_per_minute
        if normalized_rl != updated.get("rate_limit_per_minute"):
            updated["rate_limit_per_minute"] = normalized_rl
            changed_fields.append("rate_limit_per_minute")

    if monthly_roll_cap is not None:
        # 0 means unlimited; schema allows 0.
        if monthly_roll_cap != updated.get("monthly_roll_cap"):
            updated["monthly_roll_cap"] = monthly_roll_cap
            changed_fields.append("monthly_roll_cap")

    if status is not None and status != updated.get("status"):
        updated["status"] = status
        changed_fields.append("status")

    # Always touch updated_at when an update is requested, matching real APIs that accept idempotent updates.
    updated["updated_at"] = now
    if updated.get("last_used_at") is None or updated.get("last_used_at") < now:
        # Updating a key counts as using the key in the control plane
        updated["last_used_at"] = now

    # persist (even if no fields effectively changed besides timestamps)
    api_keys[idx] = updated
    _save("api_keys.json", _wrap_rows(api_keys, api_keys_raw))

    latency_ms = int((time.time() - started) * 1000)

    return {
        "api_key": updated,
        "changed_fields": changed_fields,
        "idempotent": (len(changed_fields) == 0),
        "latency_ms": latency_ms,
    }
